// Report account balances from a ledger file.

const encoder = new TextEncoder();

// Parse an unsigned decimal amount with two fraction digits into exact cents.
function to_cents(amount: string): bigint {
  const match = /^(\d+)\.(\d{2})$/.exec(amount);
  if (match === null) {
    throw new Error(`bad amount: ${amount}`);
  }
  return BigInt(match[1]) * 100n + BigInt(match[2]);
}

function format_cents(cents: bigint): string {
  const sign = cents < 0n ? "-" : "";
  const magnitude = cents < 0n ? -cents : cents;
  const fraction = String(magnitude % 100n).padStart(2, "0");
  return `${sign}${magnitude / 100n}.${fraction}`;
}

function compare_bytes(left: string, right: string): number {
  const a = encoder.encode(left);
  const b = encoder.encode(right);
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    if (a[i] !== b[i]) {
      return a[i] - b[i];
    }
  }
  return a.length - b.length;
}

// Balance descending, then account name ascending by bytes.
function by_report_order(
  left: [string, bigint],
  right: [string, bigint],
): number {
  if (left[1] !== right[1]) {
    return left[1] > right[1] ? -1 : 1;
  }
  return compare_bytes(left[0], right[0]);
}

function read_ledger(path: string): string[] {
  return Deno.readTextFileSync(path).split(/\r?\n/);
}

function fields(line: string | undefined): string[] {
  return (line ?? "").trim().split(/\s+/).filter((field) => field !== "");
}

function main() {
  const lines = read_ledger(Deno.args[0]);
  const n = Number(fields(lines[0])[1] ?? 0);

  const balances = new Map<string, bigint>();
  for (let index = 0; index < n; index++) {
    const [account, kind, amount] = fields(lines[1 + index]);
    let signed: bigint;
    if (kind === "credit") {
      signed = to_cents(amount);
    } else if (kind === "debit") {
      signed = -to_cents(amount);
    } else {
      console.log(`ERROR line ${index + 1}`);
      return;
    }
    balances.set(account, (balances.get(account) ?? 0n) + signed);
  }

  const entries = [...balances.entries()].sort(by_report_order);
  const output: string[] = [];
  let total = 0n;
  for (const [account, balance] of entries) {
    output.push(`${account} ${format_cents(balance)}`);
    total += balance;
  }
  output.push(`TOTAL ${format_cents(total)}`);
  console.log(output.join("\n"));
}

main();

